import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph User + Dev Monthly Meeting 2024-05-23","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meeting 2024-05-23","date":"2024-05-23T00:00:00.000Z","updated":"2024-05-31T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","用户反馈","社区发展"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-05-23.md","filePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-05-23.md","lastUpdated":1780460162000}'),a={name:"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-05-23.md"};function n(s,e,i,h,_,g){return r(),o("div",null,[...e[0]||(e[0]=[l('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>本次Ceph用户和开发者月度会议主要讨论了社区调查反馈，重点关注了Orchestration和Performance方面的问题。会议旨在通过收集社区成员的实时反馈，更好地理解用户需求并改进Ceph的功能和性能。</p><h4 id="关键讨论点" tabindex="-1">关键讨论点 <a class="header-anchor" href="#关键讨论点" aria-label="Permalink to &quot;关键讨论点&quot;">​</a></h4><ol><li><p><strong>Orchestration反馈</strong></p><ul><li><strong>部署目标</strong>：大多数用户使用裸机进行部署，较少使用容器。</li><li><strong>Orchestration系统</strong>：SEF ADM最受欢迎，其次是自制的Orchestration系统。</li><li><strong>用户反馈</strong>：SEF ADM被认为简单可靠，但存在命令复杂、日志难以调试等问题。自制Orchestration系统则提供了更多控制和信任。</li></ul></li><li><p><strong>Performance反馈</strong></p><ul><li><strong>集群事件影响</strong>：监控同步、OSD不可用等事件对性能有显著影响。</li><li><strong>EC插件使用</strong>：大多数用户使用默认的EC插件，如jerasure和reed_sol_van。</li><li><strong>Op调度器</strong>：mclock是常用的Op调度器，但存在文档不足和需要手动调优的问题。</li></ul></li><li><p><strong>Telemetry模块</strong>：约50%的用户未启用Telemetry模块，主要原因是缺乏对功能的了解和对隐私安全的担忧。</p></li><li><p><strong>用户建议和反馈</strong></p><ul><li><strong>改进建议</strong>：用户提出了对SEF ADM自动化程度、日志调试、OSD创建过程的改进建议。</li><li><strong>技术讨论</strong>：涉及SEF ADM是否应支持非容器化部署的讨论，以及Telemetry模块的数据安全和隐私问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>改进方向</strong>：社区将根据调查反馈，特别是在Orchestration和Performance方面的具体问题，进行针对性的改进。</li><li><strong>文档更新</strong>：将更新和改进相关文档，特别是关于mclock和SEF ADM的使用指南。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>跟踪问题</strong>：社区成员被鼓励提出具体的问题和反馈，通过创建Tracker来跟踪和解决这些问题。</li><li><strong>社区参与</strong>：鼓励更多的社区成员参与到用户委员会中，特别是那些对特定主题（如stretch clusters）有兴趣的成员。</li><li><strong>持续反馈</strong>：会议结束后，调查问卷将继续开放一段时间，以便收集更多的反馈。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了社区反馈的重要性，并承诺将根据这些反馈进行改进，以提高Ceph的性能和用户体验。同时，鼓励社区成员积极参与，共同推动Ceph的发展。</p>',10)])])}const d=t(a,[["render",n]]);export{c as __pageData,d as default};
